SELECT
id, user_id, related_id, amount, type, method, status, create_time
FROM payments
WHERE delete_flag = 0

    AND user_id = #{userId}


    AND type = #{queryDTO.type}


    AND method = #{queryDTO.method}


    AND status = #{queryDTO.status}


    AND DATE(create_time) >= #{queryDTO.startDate}


    AND DATE(create_time) <= #{queryDTO.endDate}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM payments
WHERE delete_flag = 0

    AND user_id = #{userId}


    AND type = #{queryDTO.type}


    AND method = #{queryDTO.method}


    AND status = #{queryDTO.status}


    AND DATE(create_time) >= #{queryDTO.startDate}


    AND DATE(create_time) <= #{queryDTO.endDate}
